const [ls, ledger] = await Promise.all([
  tools.pwsh({ description: "List oleans for S1845/S1850 area", command: "Get-ChildItem 'D:\\lean\\.lake\\build\\lib\\lean\\tmp\\sheaf\\xif\\paper' -Filter '*S1845*' | Select-Object Name,Length,LastWriteTime | Format-Table -AutoSize; Get-ChildItem 'D:\\lean\\.lake\\build\\lib\\lean\\tmp\\sheaf\\xif\\paper' -Filter '*S1850*' | Format-Table -AutoSize" }),
  tools.grep({ pattern: "S1845|S1850|S1831AlgEnd|S1756FirstMissing", path: "D:\\lean\\AUDIT_LEDGER.md" }),
]);
console.log(ls.stdout.text);
console.log("=== ledger matches ===");
console.log(ledger.matches.slice(-40).map(m => `${m.lineNumber}: ${m.line.slice(0,300)}`).join("\n"));
", "description": "Check oleans and audit ledger mentions"}

